insert into public.cards (id, owner_id, data) values
('b8e234f4-aeb4-53ef-9e2d-f8ff256a190e', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "b8e234f4-aeb4-53ef-9e2d-f8ff256a190e", "code": "14ER-029", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "ondes mécaniques", "onde mécanique", "piège"], "front": "Une onde mécanique peut-elle se propager **dans le vide** ?", "back": "**Non** : il lui faut un milieu matériel (solide, liquide ou gaz). Dans l''espace, aucun son ne se propage.\nLes ondes **électromagnétiques** (lumière, radio) se propagent, elles, aussi dans le vide.", "createdAt": 1794071300000, "updatedAt": 1794071300000, "ocrDone": true}'::jsonb),
('04bab895-a20c-5513-9c0f-334340f08f54', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "04bab895-a20c-5513-9c0f-334340f08f54", "code": "14ER-030", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "ondes mécaniques", "transversale", "exemple"], "front": "**Exemple** : la ola. Que fait chaque spectateur ? De quel type d''onde s''agit-il ?", "back": "Il se lève puis se rassoit **sur place** : pas de transport de matière.\nSon mouvement (vertical) est perpendiculaire à la propagation (le long des gradins) : onde **transversale**.", "createdAt": 1794071300001, "updatedAt": 1794071300001, "ocrDone": true}'::jsonb),
('49249118-dcec-5288-9ac7-94458c4b1756', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "49249118-dcec-5288-9ac7-94458c4b1756", "code": "14ER-031", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "ondes mécaniques", "longitudinale", "exemple"], "front": "Son, ressort, ondes sismiques : transversales ou longitudinales ?", "back": "**Son** et **ressort comprimé** : longitudinales (compressions dans la direction de propagation).\n**Séismes** : ondes P longitudinales (les plus rapides), ondes S transversales.", "createdAt": 1794071300002, "updatedAt": 1794071300002, "ocrDone": true}'::jsonb),
('a329c40d-59b3-5ebc-b567-a34d906c6995', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "a329c40d-59b3-5ebc-b567-a34d906c6995", "code": "14ER-032", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "ondes mécaniques", "retard", "célérité"], "front": "Un point $M''$ situé après $M$ : que fait-il quand l''onde passe ?", "back": "Il **reproduit** le mouvement de $M$, avec un **retard** $\\tau = t'' - t$.\n$v = \\dfrac{MM''}{\\tau}$, soit $\\tau = \\dfrac{MM''}{v}$", "createdAt": 1794071300003, "updatedAt": 1794071300003, "ocrDone": true}'::jsonb),
('61984279-9fed-59ca-8817-be941fb4280b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "61984279-9fed-59ca-8817-be941fb4280b", "code": "14ER-033", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "ondes mécaniques", "célérité", "méthode"], "front": "Méthode : trouver la **célérité** à partir de deux photos d''une corde (ou de deux instants) ?", "back": "Repérer la position du **front** de la perturbation aux deux instants.\n$v = \\dfrac{x_2 - x_1}{t_2 - t_1}$ (distance en m, durée en s).\nEx. : front à 0,60 m à 0,10 s puis à 1,50 m à 0,25 s : $v = \\dfrac{0{,}90}{0{,}15} = 6{,}0\\ \\mathrm{m \\cdot s^{-1}}$", "createdAt": 1794071300004, "updatedAt": 1794071300004, "ocrDone": true}'::jsonb),
('337d6dfb-1938-5fd5-bf3a-8b3c8070d4d9', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "337d6dfb-1938-5fd5-bf3a-8b3c8070d4d9", "code": "14ER-034", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "ondes mécaniques", "célérité", "exemple"], "front": "**Exemple** : on entend le tonnerre 4,5 s après l''éclair. Distance de l''orage ?", "back": "La lumière arrive quasi instantanément ; le son met 4,5 s.\n$d = v \\times \\Delta t = 340 \\times 4{,}5 \\approx 1{,}5 \\times 10^3\\ \\mathrm{m}$, soit environ 1,5 km.", "createdAt": 1794071300005, "updatedAt": 1794071300005, "ocrDone": true}'::jsonb),
('04d172b2-008d-57bc-a7c8-3f1a30ab4fe0', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "04d172b2-008d-57bc-a7c8-3f1a30ab4fe0", "code": "14ER-035", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "ondes mécaniques", "phase", "définition"], "front": "Points **en phase** et points **en opposition de phase** : définition ?", "back": "**En phase** : à tout instant dans le même état (sommets en même temps). Distants de $\\lambda$, $2\\lambda$, $3\\lambda$…\n**Opposition de phase** : à tout instant dans des états opposés (l''un en haut, l''autre en bas). Distants de $\\dfrac{\\lambda}{2}$, $\\dfrac{3\\lambda}{2}$…", "createdAt": 1794071300006, "updatedAt": 1794071300006, "ocrDone": true}'::jsonb),
('c2421912-2ce7-534c-935e-2ce775839081', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "c2421912-2ce7-534c-935e-2ce775839081", "code": "14ER-036", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "ondes mécaniques", "longueur d''onde", "définition"], "front": "Définir la **longueur d''onde** avec la notion de points en phase.", "back": "C''est la **plus petite distance** entre deux points du milieu **en phase**.\nC''est aussi la distance parcourue par l''onde pendant une période : $\\lambda = v\\,T$.", "createdAt": 1794071300007, "updatedAt": 1794071300007, "ocrDone": true}'::jsonb),
('2fec8191-82bd-5cc1-a693-0d718709e83b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "2fec8191-82bd-5cc1-a693-0d718709e83b", "code": "14ER-037", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "ondes mécaniques", "longueur d''onde", "piège", "méthode"], "front": "**Piège** : on mesure 4,0 cm entre la 1re et la 6e crête. Que vaut $\\lambda$ ?", "back": "Entre 6 crêtes, il y a **5** intervalles, donc $5\\lambda = 4{,}0$ cm et $\\lambda = 0{,}80$ cm.\nMesurer plusieurs $\\lambda$ (ou plusieurs $T$) rend la mesure plus précise.", "createdAt": 1794071300008, "updatedAt": 1794071300008, "ocrDone": true}'::jsonb),
('a5f131af-082e-5322-b0e6-ec6f7c550314', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "a5f131af-082e-5322-b0e6-ec6f7c550314", "code": "14ER-038", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "ondes mécaniques", "période", "exemple"], "front": "**Exemple** : cuve à ondes, $f = 20$ Hz et $\\lambda = 1{,}0$ cm. Période et célérité ?", "back": "$T = \\dfrac{1}{f} = 0{,}050$ s $= 50$ ms\n$v = \\lambda \\times f = 0{,}010 \\times 20 = 0{,}20\\ \\mathrm{m \\cdot s^{-1}}$ (penser à convertir les cm en m).", "createdAt": 1794071300009, "updatedAt": 1794071300009, "ocrDone": true}'::jsonb),
('8bc27920-4893-51ff-a873-18171005439b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "8bc27920-4893-51ff-a873-18171005439b", "code": "14ER-039", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "ondes mécaniques", "longueur d''onde", "période"], "front": "Une crête passe en $A$ à l''instant $t_1$. Où est-elle à $t_1 + T$ ?", "back": "Une **longueur d''onde** plus loin : à la place de la crête suivante.\nPendant une période, l''onde avance de $\\lambda$.", "createdAt": 1794071300010, "updatedAt": 1794071300010, "ocrDone": true}'::jsonb),
('a8188981-7393-5ad4-8c1b-f9e5c4d10a4a', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "a8188981-7393-5ad4-8c1b-f9e5c4d10a4a", "code": "14ER-040", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "ondes mécaniques", "célérité", "piège"], "front": "**Écho** (sonar, échographie) : comment calculer la distance de l''obstacle ?", "back": "L''onde fait un **aller-retour** : $2d = v \\times \\Delta t$, donc $d = \\dfrac{v \\times \\Delta t}{2}$.\nEx. : écho après 0,40 s dans l''eau ($1\\,500\\ \\mathrm{m \\cdot s^{-1}}$) : $d = 300$ m.", "createdAt": 1794071300011, "updatedAt": 1794071300011, "ocrDone": true}'::jsonb),
('7c1a983d-5a72-57d3-a20e-d657753319ce', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "7c1a983d-5a72-57d3-a20e-d657753319ce", "code": "14ER-041", "origin": "ER", "subject": "Physique-Chimie", "level": "1re", "theme": "Signaux", "tags": ["1re", "Signaux", "cours", "ondes mécaniques", "amplitude", "piège"], "front": "En s''éloignant de la source, l''**amplitude** diminue. Qu''en est-il de $T$, $\\lambda$ et $v$ ?", "back": "Ils **ne changent pas** : la diminution d''amplitude vient de l''**amortissement** (l''énergie se disperse).\n$T$ dépend de la source, $v$ du milieu, et $\\lambda = v\\,T$.", "createdAt": 1794071300012, "updatedAt": 1794071300012, "ocrDone": true}'::jsonb);
