insert into public.tutoring_files (id, group_id, author_id, data) values ('538dec87-9916-5a0a-83d0-22ed352929e3', '3c6873cc-cb98-4b74-a154-54b8730cdeb8', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "538dec87-9916-5a0a-83d0-22ed352929e3", "groupId": "3c6873cc-cb98-4b74-a154-54b8730cdeb8", "sessionId": "49950f96-db4a-4851-a2d4-3d2e7c7398c2", "mediaId": "sout/3c6873cc-cb98-4b74-a154-54b8730cdeb8/f9b493c7-9476-5b58-b1aa-d81a39885aa7", "name": "1ere_Ondes_mécaniques_Constance.pdf", "size": 235782, "type": "application/pdf", "authorId": "768856f9-b733-490b-9a10-701b0d8b3fd8", "byStudent": false, "createdAt": 1794071300000}'::jsonb) on conflict (id) do nothing;
